package example.pricing;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;

@RestController
public final class QuoteController {
  private final PricingService pricing;
  public QuoteController(PricingService pricing) { this.pricing = pricing; }
  public record QuoteRequest(@NotBlank @Size(min = 2, max = 12) String sku) {}
  public record QuoteResponse(String sku, String unitPrice) {}
  public record QuoteError(String code) {}

  @PostMapping("/quotes")
  public ResponseEntity<QuoteResponse> quote(@Valid @RequestBody QuoteRequest request) {
    String sku = request.sku().trim();
    return ResponseEntity.status(HttpStatus.CREATED)
        .body(new QuoteResponse(sku, pricing.quote(sku).toPlainString()));
  }

  @ExceptionHandler(IllegalStateException.class)
  public ResponseEntity<QuoteError> unavailable() {
    return ResponseEntity.status(HttpStatus.SERVICE_UNAVAILABLE)
        .body(new QuoteError("pricing-unavailable"));
  }
}
